INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('9f4f5035-2c4d-4b3b-9464-3406780937d7', 'a1b2c3d4-1111-4000-8000-000000000001', 4, 'O Exame de Consciência', 'Olhando o dia com os olhos de Deus', '{"intro": "O Exame de Consci\u00eancia, popularizado por Santo In\u00e1cio, \u00e9 uma ora\u00e7\u00e3o noturna poderosa. Em 5 passos simples, voc\u00ea revisa o dia com gratid\u00e3o, reconhece as mo\u00e7\u00f5es interiores, identifica onde falhou e planeja o amanh\u00e3. N\u00e3o \u00e9 uma sess\u00e3o de culpa \u2014 \u00e9 um momento de honestidade amorosa diante de Deus. Muitos santos consideravam esta a ora\u00e7\u00e3o mais importante do dia.", "prayer": "Senhor, ajuda-me a ver meu dia com Teus olhos. Onde falhei, d\u00e1-me Teu perd\u00e3o. Onde acertei, d\u00e1-me Tua humildade. Am\u00e9m.", "practice": "Hoje \u00e0 noite, fa\u00e7a o Exame em 5 passos: 1) Agrade\u00e7a; 2) Pe\u00e7a luz ao Esp\u00edrito; 3) Reveja o dia; 4) Pe\u00e7a perd\u00e3o; 5) Planeje o amanh\u00e3 com Deus.", "scripture": "\"Examina-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o; prova-me e conhece os meus pensamentos.\" \u2014 Sl 139,23", "reflection": "No final do dia, como voc\u00ea se sente? Consegue identificar momentos em que Deus agiu na sua vida hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;